const listCockpitArtifacts = `-- name: ListCockpitArtifacts :many
WITH candidates AS MATERIALIZED (
SELECT a.id,a.title,a.archived_at,a.current_version_id FROM cockpit_artifact a
WHERE a.workspace_id=$1
AND ($4::uuid IS NOT NULL OR $5::uuid IS NULL OR a.project_id=$5)
AND ($4::uuid IS NOT NULL OR $6::uuid IS NULL OR a.module_id=$6)
AND ($7::uuid IS NULL OR a.source_issue_id=$7)
AND (cardinality($8::uuid[])=0 OR a.id=ANY($8::uuid[]))
AND ($4::uuid IS NULL OR
 ($9::text IN ('owned','all') AND a.owner_node_id=$4) OR
 ($9::text IN ('referenced','all') AND EXISTS(SELECT 1 FROM cockpit_artifact_node_reference r WHERE r.workspace_id=a.workspace_id AND r.artifact_id=a.id AND r.node_id=$4 AND r.removed_at IS NULL)))
), filtered AS MATERIALIZED (
SELECT a.id FROM candidates a LEFT JOIN cockpit_artifact_version v ON v.workspace_id=$1 AND v.id=a.current_version_id
WHERE ($10::text='' OR a.title ILIKE '%'||$10||'%')
AND ($11::text='' OR CASE WHEN a.archived_at IS NOT NULL THEN 'archived' WHEN a.current_version_id IS NULL THEN 'draft' WHEN v.capture_status IN ('queued','running','retry_wait') THEN 'capturing' WHEN v.capture_status='needs_attention' THEN 'needs_attention' WHEN v.capture_status='ready' AND v.decision IN ('pending','approved','changes_requested','rejected') THEN v.decision ELSE 'unknown' END=$11)
)
SELECT a.id, a.workspace_id, a.owner_node_id, a.project_id, a.module_id, a.source_issue_id, a.authorized_producer_issue_id, a.creation_key, a.request_hash, a.created_by, a.title, a.description, a.reviewer_id, a.revision, a.current_version_id, a.approved_version_id, a.archived_at, a.archived_by, a.created_at, a.updated_at FROM filtered f JOIN cockpit_artifact a ON a.workspace_id=$1 AND a.id=f.id
WHERE $2::uuid IS NULL OR a.id>$2 ORDER BY a.id LIMIT $3
`

